const video = document.getElementById('camera-feed');
        const canvas = document.getElementById('analysis-canvas');
        const ctx = canvas.getContext('2d');
        const overlay = document.getElementById('start-overlay');
        const dashboard = document.getElementById('dashboard');
        const tempVal = document.getElementById('temp-val');
        const impactVal = document.getElementById('impact-val');
        const tempMarker = document.getElementById('temp-marker');
        const recTitle = document.getElementById('rec-title');
        const recText = document.getElementById('rec-text');
        const recBox = document.getElementById('rec-box');
        let isRunning = false;
        async function startCamera() {
            try {
                const constraints = {
                    video: {
                        facingMode: "environment",
                        width: { ideal: 640 },
                        height: { ideal: 480 }
                    }
                };
                const stream = await navigator.mediaDevices.getUserMedia(constraints);
                video.srcObject = stream;
                await video.play();
                overlay.classList.add('hidden');
                dashboard.classList.remove('hidden');
                document.getElementById('perm-warning').classList.add('hidden');
                isRunning = true;
                processFrame();
            } catch (err) {
                console.error("Camera Error:", err);
                alert("Camera access denied. Please enable permissions to analyze your environment.");
            }
        }
        function processFrame() {
            if (!isRunning) return;
            canvas.width = 100;
            canvas.height = 100;
            ctx.drawImage(video, 0, 0, 100, 100);
            const frame = ctx.getImageData(0, 0, 100, 100);
            const data = frame.data;
            let r = 0, g = 0, b = 0;
            const count = data.length / 4;
            for (let i = 0; i < data.length; i += 4) {
                r += data[i];
                g += data[i + 1];
                b += data[i + 2];
            }
            r = Math.floor(r / count);
            g = Math.floor(g / count);
            b = Math.floor(b / count);
            const kelvin = rgbToKelvin(r, g, b);
            updateUI(kelvin);
            requestAnimationFrame(processFrame);
        }
        function rgbToKelvin(r, g, b) {
            // Human-Logic Algorithmic Sequence:
            // Estimated Kelvin = Neutral Point (5500) minus (Red-to-Blue normalization * Scale Factor)
            const total = r + g + b;
            if (total === 0) return 5500;
            // normalized difference n
            const n = (r - b) / (r + b + g);
            // Map the difference n to the Kelvin scale
            // Scaling Constant = 7000 (empirical value for camera sensor mapping)
            const k = 5500 - (n * 7000);
            return Math.max(1000, Math.min(10000, Math.round(k)));
        }
        function updateUI(k) {
            tempVal.innerText = `${k} K`;
            const percent = ((k - 1000) / 9000) * 100;
            tempMarker.style.left = `${Math.max(0, Math.min(100, percent))}%`;
            if (k < 3000) {
                impactVal.innerText = "Low (Safe)";
                impactVal.className = "text-2xl font-black text-orange-400 mt-1";
                recTitle.innerText = "NIGHT-TIME SAFE";
                recText.innerText = "This source contains very low HEV blue light. It is ideal for pre-sleep relaxation.";
                recBox.className = "p-10 rounded-[2.5rem] border-2 border-orange-500/20 bg-orange-950/40 text-center shadow-xl";
                recTitle.className = "text-orange-300 text-xl font-black mb-3 uppercase tracking-tighter";
            } else if (k < 5000) {
                impactVal.innerText = "Moderate Risk";
                impactVal.className = "text-2xl font-black text-yellow-400 mt-1";
                recTitle.innerText = "CAUTION ADVISED";
                recText.innerText = "Balanced spectrum. Suitable for late afternoon, but avoid within 2 hours of bedtime.";
                recBox.className = "p-10 rounded-[2.5rem] border-2 border-yellow-500/20 bg-yellow-950/40 text-center shadow-xl";
                recTitle.className = "text-yellow-300 text-xl font-black mb-3 uppercase tracking-tighter";
            } else {
                impactVal.innerText = "High Alert";
                impactVal.className = "text-2xl font-black text-blue-400 mt-1";
                recTitle.innerText = "MELATONIN SUPPRESSED";
                recText.innerText = "High HEV spike detected. This light source is signaling your brain to remain in 'Noon Alertness' mode.";
                recBox.className = "p-10 rounded-[2.5rem] border-2 border-blue-500/20 bg-blue-950/40 text-center shadow-xl";
                recTitle.className = "text-blue-300 text-xl font-black mb-3 uppercase tracking-tighter";
            }
        }
